args.command:
cd /private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.YejPLZ/app && mkdir -p /tmp/lumail-research/shots && cat > /tmp/lumail-research/shot.mjs <<'EOF'
import puppeteer from '/private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.YejPLZ/app/node_modules/puppeteer-core/lib/esm/puppeteer/puppeteer-core.js';
const b = await puppeteer.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless:true, args:['--no-sandbox']});
const p = await b.newPage();
await p.setViewport({width:1440,height:900,deviceScaleFactor:1});
for (const [name,url,scheme] of [['home-light','https://lumail.io','light'],['home-dark','https://lumail.io','dark']]) {
  await p.emulateMediaFeatures([{name:'prefers-color-scheme',value:scheme}]);
  await p.goto(url,{waitUntil:'networkidle2',timeout:45000});
  await new Promise(r=>setTimeout(r,1500));
  await p.screenshot({path:`/tmp/lumail-research/shots/${name}-top.png`});
  await p.evaluate(()=>window.scrollTo(0,1000)); await new Promise(r=>setTimeout(r,1000));
  await p.screenshot({path:`/tmp/lumail-research/shots/${name}-2.png`});
  await p.evaluate(()=>window.scrollTo(0,2200)); await new Promise(r=>setTimeout(r,1000));
  await p.screenshot({path:`/tmp/lumail-research/shots/${name}-3.png`});
}
await b.close();
EOF
node /tmp/lumail-research/shot.mjs && ls /tmp/lumail-research/shots

