    dyn.push((t) => { marq.style.transform = `translateX(${-(((t - b) * 120) % marqLoop)}px)`; });
    drift('#s7a', T.s7a, T.s7b);

    /* ---------- S7b : pricing (33.75 → 39.375) ---------- */
    wipe('#s7b', '#s7a', T.s7b, 'down', { dur: 0.66 });
