  }
  function rise(sel, t, o = {}) {
    tl.fromTo(sel, { y: o.y ?? 34, opacity: 0 }, { y: 0, opacity: 1, duration: o.d ?? 0.7, ease: o.ease ?? 'expo.out', stagger: o.s ?? 0 }, t);
  }
  function words(sel, t, o = {}) {
