import puppeteer from 'puppeteer-core';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const browser = await puppeteer.launch({ executablePath: CHROME, headless: true, args: ['--allow-file-access-from-files'], defaultViewport: { width: 1920, height: 1080 } });
const page = await browser.newPage();
page.on('pageerror', (e) => console.log('[pageerror]', e.message));
await page.goto(pathToFileURL(path.resolve('src/scene.html')).href);
await page.evaluate(() => window.__ready);

const checks = [
  { t: 2.4, scene: '#s1', blocks: ['#s1 .copy', '#s1 .chip:nth-of-type(2)'] },
  { t: 7.0, scene: '#s2', blocks: ['#logoBig', '#s2 .word', '#s2 .intro', '#s2 .tag'] },
  { t: 12.5, scene: '#s3', blocks: ['#k3', '#s3 .hd', '#s3sub', '#s3al', '#s3apps', '#s3card'] },
  { t: 18.8, scene: '#s4', blocks: ['#s4 .kick', '#s4 .hd', '#ed', '#pv', '#tighter'] },
  { t: 24.3, scene: '#s5', blocks: ['#s5 .kick', '#s5 .hd', '#pubcard', '#nA', '#nB', '#nC', '#nD', '#nY', '#nN'] },
  { t: 29.0, scene: '#s6', blocks: ['#s6 .kick', '#s6 .hd', '#s6sub', '#code', '#lanes'] },
  { t: 33.0, scene: '#s7a', blocks: ['#s7a .kick', '#s7a .hd', '#s7card', '#stamp', '.marq-l', '.marq'] },
  { t: 38.6, scene: '#s7b', blocks: ['#s7b .kick', '#s7b .hd', '#never', '#meter', '#pFree', '#pCrt'] },
  { t: 41.5, scene: '#s8a', blocks: ['#s8a .top', '#num8', '#s8a .numl', '#quote'] },
  { t: 44.6, scene: '#s8b', blocks: ['#lock', '#tag8', '#cta', '#fine'] },
];

for (const c of checks) {
  await page.evaluate((t) => window.seekTo(t), c.t);
  const res = await page.evaluate((c) => {
    const rect = (el) => { const r = el.getBoundingClientRect(); return { x: r.left, y: r.top, r: r.right, b: r.bottom, w: r.width, h: r.height }; };
    const out = { scene: c.scene, t: c.t, boxes: {}, overlaps: [], oob: [], overflow: [] };
    const els = c.blocks.map((s) => [s, document.querySelector(s)]);
    for (const [s, el] of els) { if (!el) { out.oob.push(`${s} MISSING`); continue; } const r = rect(el); out.boxes[s] = `${Math.round(r.x)},${Math.round(r.y)} → ${Math.round(r.r)},${Math.round(r.b)}`; if (r.x < -2 || r.y < -2 || r.r > 1922 || r.b > 1082) out.oob.push(s); }
    for (let i = 0; i < els.length; i++) for (let j = i + 1; j < els.length; j++) {
      if (!els[i][1] || !els[j][1]) continue; const a = rect(els[i][1]), b = rect(els[j][1]);
      const ox = Math.min(a.r, b.r) - Math.max(a.x, b.x), oy = Math.min(a.b, b.b) - Math.max(a.y, b.y);
      if (ox > 4 && oy > 4) out.overlaps.push(`${els[i][0]} × ${els[j][0]} (${Math.round(ox)}×${Math.round(oy)})`);
    }
    document.querySelectorAll(c.scene + ' *').forEach((e) => {
      if (e.children.length === 0 && e.textContent.trim() && getComputedStyle(e).overflow === 'visible') {
        const r = e.getBoundingClientRect(); if (r.right > 1800 + 60 || r.left < 60 && r.width > 0 && !e.closest('.ov')) out.overflow.push(`${e.className || e.tagName}:"${e.textContent.trim().slice(0, 24)}" ${Math.round(r.left)}..${Math.round(r.right)}`);
      }
    });
    return out;
  }, c);
  console.log(`\n== ${c.scene} @${c.t}`);
  for (const [k, v] of Object.entries(res.boxes)) console.log('  ', k.padEnd(18), v);
  if (res.overlaps.length) console.log('  OVERLAPS:', res.overlaps.join(' | '));
  if (res.oob.length) console.log('  OOB:', res.oob.join(', '));
  if (res.overflow.length) console.log('  EDGE-TEXT:', res.overflow.slice(0, 6).join(' | '));
}
await browser.close();

