  [29.2, '#otp', '#tr2', 'S6 otp inside track'],
  [29.2, '#dlv', '#tr2', 'S6 delivered chip inside track'],
  [33.0, '#m4', '#s7card .term', 'S7a done line inside card'],
  [38.7, '#pFree ul', '#pFree', 'S7b free list inside plan'],
  [38.7, '#pCrt ul', '#pCrt', 'S7b creator list inside plan'],
];
for (const [t, inner, outer, label] of pairs) {
  await page.evaluate((tt) => window.seekTo(tt), t);
  const r = await page.evaluate((inner, outer) => {
    const a = document.querySelector(inner).getBoundingClientRect(), b = document.querySelector(outer).getBoundingClientRect();
    return { top: a.top - b.top, bottom: b.bottom - a.bottom, left: a.left - b.left, right: b.right - a.right };
  }, inner, outer);
  const bad = Object.values(r).some((v) => v < 0);
  console.log(`${bad ? 'FAIL' : 'ok  '} ${label.padEnd(42)} top ${r.top.toFixed(0)} bottom ${r.bottom.toFixed(0)} left ${r.left.toFixed(0)} right ${r.right.toFixed(0)}`);
}

// plan li vs foot
await page.evaluate(() => window.seekTo(38.7));
console.log(await page.evaluate(() => ['#pFree', '#pCrt'].map((s) => {
