// S1 text bounds
await page.evaluate(() => window.seekTo(2.4));
console.log('S1 lines', await page.evaluate(() => [...document.querySelectorAll('#s1 .hd .ln')].map((l) => { const r = l.getBoundingClientRect(); return `${Math.round(r.left)},${Math.round(r.top)}→${Math.round(r.right)},${Math.round(r.bottom)}`; })));
console.log('S1 chips', await page.evaluate(() => [...document.querySelectorAll('#s1 .chip')].map((c) => { const r = c.getBoundingClientRect(); return `${Math.round(r.left)},${Math.round(r.top)}→${Math.round(r.right)},${Math.round(r.bottom)}`; })));
await page.evaluate(() => window.seekTo(1.7));
console.log('S1 chips@1.7', await page.evaluate(() => [...document.querySelectorAll('#s1 .chip')].map((c) => { const r = c.getBoundingClientRect(); return `${Math.round(r.left)},${Math.round(r.top)}→${Math.round(r.right)},${Math.round(r.bottom)}`; })));
// S2 lockup center
await page.evaluate(() => window.seekTo(7.0));
console.log('S2', await page.evaluate(() => { const l = document.querySelector('#logoBig').getBoundingClientRect(), w = document.querySelector('#s2 .word span').getBoundingClientRect(); const cx = (l.left + w.right) / 2; return `tile ${Math.round(l.left)}-${Math.round(l.right)}, word ${Math.round(w.left)}-${Math.round(w.right)}, lockup center ${Math.round(cx)}`; }));
console.log('S2 tag lines', await page.evaluate(() => [...document.querySelectorAll('#s2 .tag .ln')].map((l) => { const r = l.getBoundingClientRect(); const kids = [...l.children].map(c=>c.getBoundingClientRect()); return `w ${Math.round(Math.min(...kids.map(k=>k.left)))}→${Math.round(Math.max(...kids.map(k=>k.right)))}`; })));
await browser.close();

