import puppeteer from 'puppeteer-core';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const url = pathToFileURL(path.resolve('index.html')).href;
const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: true,
  args: ['--allow-file-access-from-files', '--hide-scrollbars'],
});
const page = await browser.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('requestfailed', (r) => errors.push('reqfail ' + r.url()));

await page.setViewport({ width: 1920, height: 1080 });
await page.goto(url, { waitUntil: 'load' });
await page.waitForFunction(() => document.querySelector('video').readyState >= 3, { timeout: 20000 });

const info = await page.evaluate(() => {
  const v = document.querySelector('video');
  return {
    title: document.title,
    headings: document.querySelectorAll('h1,h2,h3,h4,h5,h6').length,
    bodyText: document.body.innerText.trim(),
    controls: v.controls,
    duration: v.duration,
    videoWidth: v.videoWidth,
    videoHeight: v.videoHeight,
    hasAudioTracks: v.audioTracks ? v.audioTracks.length : 'n/a',
    src: v.currentSrc.split('/').pop(),
  };
});
console.log(JSON.stringify(info));

const sizes = [[1920, 1080], [1280, 720], [1000, 1000], [1600, 500], [500, 900], [2560, 1080], [390, 844]];
for (const [w, h] of sizes) {
  await page.setViewport({ width: w, height: h });
  const r = await page.evaluate(() => {
    const b = document.querySelector('video').getBoundingClientRect();
    return { x: b.x, y: b.y, w: b.width, h: b.height, sw: document.documentElement.scrollWidth, sh: document.documentElement.scrollHeight };
  });
  const ratio = r.w / r.h;
  const fits = r.x >= -0.5 && r.y >= -0.5 && r.x + r.w <= w + 0.5 && r.y + r.h <= h + 0.5;
  const fillsAxis = Math.abs(r.w - w) < 1 || Math.abs(r.h - h) < 1;
  console.log(`${w}x${h}: box ${r.w.toFixed(1)}x${r.h.toFixed(1)} @ ${r.x.toFixed(1)},${r.y.toFixed(1)} ratio ${ratio.toFixed(4)} (16/9=${(16 / 9).toFixed(4)}) fits=${fits} fillsAxis=${fillsAxis} noScroll=${r.sw <= w && r.sh <= h}`);
}

await page.setViewport({ width: 1920, height: 1080 });
await page.mouse.click(960, 450);
await new Promise((r) => setTimeout(r, 200));
let st = await page.evaluate(() => { const v = document.querySelector('video'); return { paused: v.paused, t: v.currentTime }; });
if (st.paused) {
  await page.evaluate(() => document.querySelector('video').play());
  st = await page.evaluate(() => { const v = document.querySelector('video'); return { paused: v.paused, t: v.currentTime }; });
}
await new Promise((r) => setTimeout(r, 2500));
const after = await page.evaluate(() => { const v = document.querySelector('video'); return { paused: v.paused, t: v.currentTime, ended: v.ended, muted: v.muted, err: v.error && v.error.code }; });
console.log('play: start', JSON.stringify(st), 'after 2.5s', JSON.stringify(after));

const out = process.env.OUT || '/tmp/lumail-player';
await page.evaluate(() => { const v = document.querySelector('video'); v.pause(); v.currentTime = 22; });
await new Promise((r) => setTimeout(r, 800));
await page.screenshot({ path: out + '-1920.png' });
await page.setViewport({ width: 900, height: 900 });
await new Promise((r) => setTimeout(r, 300));
await page.screenshot({ path: out + '-900.png' });

await page.setViewport({ width: 1920, height: 1080 });
await page.evaluate(() => { const v = document.querySelector('video'); v.currentTime = 44.5; v.muted = true; return v.play(); });
await new Promise((r) => setTimeout(r, 1500));
console.log('end:', JSON.stringify(await page.evaluate(() => { const v = document.querySelector('video'); return { ended: v.ended, t: v.currentTime }; })));
console.log('errors:', JSON.stringify(errors));
await browser.close();

